🐛 Bug
Memory corruption between two threads: one calling select and another moving a tensor to kCUDA.
To Reproduce
Build the attached file and execute it. I've included a small CMakeLists.txt that can be used for an easy build
Steps to reproduce the behavior:

Save the following as test_threading_safety.cpp

#include <thread>
#include <chrono>
#include <torch/torch.h>

static bool run = true;

void assign_to_tensor() {
        while (run) {
            torch::Tensor tensor_to_fill = torch::ones({8192});
            for (size_t fill_index = 0; fill_index < 8192; ++fill_index) {
                tensor_to_fill.select(0, fill_index) = 4.2;
            }
        }
}

void move_tensor() {
    std::vector<torch::Tensor> x;
    while(run) {
        auto tensor_to_move = torch::ones(10000);
        tensor_to_move = tensor_to_move.to(torch::kCUDA);
    }
}

int main() {
    std::vector<std::thread> t1;
    // 1 thread has a reasonably high chance of triggering a segfault, more threads makes it more or less 100%
    for (size_t thread_count = 0; thread_count < 10; ++thread_count) {
        t1.emplace_back(std::thread(assign_to_tensor));
        t1.emplace_back(std::thread(move_tensor));
    }

    std::cout << "Waiting 5 seconds." << std::endl;
    std::this_thread::sleep_for(std::chrono::seconds(5));
    std::cout << "Done... notifying threads to stop." << std::endl;
    run = false;

    for (auto &thread : t1) {
        thread.join();
    }
    return 0;
}

